#!/usr/bin/env python3
"""Command-line statistics calculator."""

import argparse
import math
import sys


def calculate(values):
    """Return min, max, sum, and average for a non-empty iterable."""
    numbers = list(values)
    if not numbers:
        raise ValueError("at least one number is required")
    return {
        "min": min(numbers),
        "max": max(numbers),
        "sum": math.fsum(numbers),
        "average": math.fsum(numbers) / len(numbers),
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description="Calculate basic statistics.")
    parser.add_argument("numbers", nargs="*", help="numbers to calculate")
    args = parser.parse_args(argv)
    try:
        values = [float(value) for value in args.numbers]
        result = calculate(values)
    except (ValueError, TypeError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    for name in ("min", "max", "sum", "average"):
        print(f"{name}: {result[name]:g}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import unittest

from stats_cli import calculate, main


class StatisticsTests(unittest.TestCase):
    def test_negative_numbers(self):
        self.assertEqual(calculate([-5, -2, -9]), {
            "min": -9, "max": -2, "sum": -16.0, "average": -16 / 3,
        })

    def test_decimals(self):
        result = calculate([1.5, 2.25, 3.25])
        self.assertAlmostEqual(result["sum"], 7.0)
        self.assertAlmostEqual(result["average"], 7 / 3)

    def test_empty_input(self):
        with self.assertRaises(ValueError):
            calculate([])

    def test_invalid_input(self):
        with self.assertRaises(ValueError):
            calculate([1, "not-a-number"])

    def test_cli_rejects_empty_input(self):
        self.assertEqual(main([]), 2)

    def test_cli_rejects_invalid_input(self):
        self.assertEqual(main(["1", "oops"]), 2)


if __name__ == "__main__":
    unittest.main()
